/**
 * Pure-JS streaming SHA-1, shaped like a Python `hashlib` module.
 *
 * The module object exposes `digest_size`, `block_size` and a `new()` /
 * `create()` factory so that it can be handed around exactly like
 * `hashlib.sha1` is in the Python original (see lib/hash/hmac.mjs and
 * lib/pbkdf2.mjs, which treat it as an opaque "digestmodule").
 */

/** Size of a SHA-1 digest in bytes. */
export const digest_size = 20;

/** Size of the SHA-1 compression block in bytes. */
export const block_size = 64;

/** Algorithm name, mirroring `hashlib.sha1().name`. */
export const name = 'sha1';

// Round constants, one per 20-round group.
const K0 = 0x5a827999;
const K1 = 0x6ed9eba1;
const K2 = 0x8f1bbcdc;
const K3 = 0xca62c1d6;

// Scratch message schedule, allocated once. Compression is synchronous and
// never re-entrant, so a single module-level buffer is safe and avoids
// allocating 320 bytes per block.
const W = new Uint32Array(80);

// Scratch buffer for the final padded block(s): at most two blocks.
const PAD = new Uint8Array(128);

/**
 * Compress one 64-byte block of `data` starting at `offset` into `h`.
 * @param {Uint32Array} h five-word chaining state, updated in place
 * @param {Uint8Array} data
 * @param {number} offset
 */
function compress(h, data, offset) {
  // Load the block as 16 big-endian words, then expand to 80.
  for (let i = 0, p = offset; i < 16; i++, p += 4) {
    W[i] = ((data[p] << 24) | (data[p + 1] << 16) | (data[p + 2] << 8) | data[p + 3]) >>> 0;
  }
  for (let i = 16; i < 80; i++) {
    const x = W[i - 3] ^ W[i - 8] ^ W[i - 14] ^ W[i - 16];
    W[i] = ((x << 1) | (x >>> 31)) >>> 0;
  }

  let a = h[0];
  let b = h[1];
  let c = h[2];
  let d = h[3];
  let e = h[4];

  // Each group has its own boolean function and constant; keeping them in
  // separate loops keeps the inner body branch-free.
  for (let i = 0; i < 20; i++) {
    const t = (((a << 5) | (a >>> 27)) + ((b & c) | (~b & d)) + e + K0 + W[i]) >>> 0;
    e = d;
    d = c;
    c = ((b << 30) | (b >>> 2)) >>> 0;
    b = a;
    a = t;
  }
  for (let i = 20; i < 40; i++) {
    const t = (((a << 5) | (a >>> 27)) + (b ^ c ^ d) + e + K1 + W[i]) >>> 0;
    e = d;
    d = c;
    c = ((b << 30) | (b >>> 2)) >>> 0;
    b = a;
    a = t;
  }
  for (let i = 40; i < 60; i++) {
    const t = (((a << 5) | (a >>> 27)) + ((b & c) | (b & d) | (c & d)) + e + K2 + W[i]) >>> 0;
    e = d;
    d = c;
    c = ((b << 30) | (b >>> 2)) >>> 0;
    b = a;
    a = t;
  }
  for (let i = 60; i < 80; i++) {
    const t = (((a << 5) | (a >>> 27)) + (b ^ c ^ d) + e + K3 + W[i]) >>> 0;
    e = d;
    d = c;
    c = ((b << 30) | (b >>> 2)) >>> 0;
    b = a;
    a = t;
  }

  h[0] = (h[0] + a) >>> 0;
  h[1] = (h[1] + b) >>> 0;
  h[2] = (h[2] + c) >>> 0;
  h[3] = (h[3] + d) >>> 0;
  h[4] = (h[4] + e) >>> 0;
}

/**
 * Incremental SHA-1 hash object, mirroring the `hashlib` hash-object API.
 */
export class SHA1 {
  constructor() {
    /** @type {Uint32Array} chaining state */
    this._h = new Uint32Array([0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0]);
    /** @type {Uint8Array} partial-block buffer */
    this._buf = new Uint8Array(64);
    /** @type {number} bytes currently held in `_buf` */
    this._len = 0;
    // Total message length in bytes, split into two 32-bit halves so that
    // messages larger than 2**53 bytes would still pad correctly.
    this._lenLo = 0;
    this._lenHi = 0;
  }

  get digest_size() {
    return digest_size;
  }

  get block_size() {
    return block_size;
  }

  get name() {
    return name;
  }

  /**
   * Absorb more bytes.
   * @param {Uint8Array} data
   * @returns {SHA1} this, for chaining
   */
  update(data) {
    if (data === undefined || data === null) return this;
    const n = data.length;
    if (n === 0) return this;

    // Advance the 64-bit byte counter (n < 2**32, so this stays exact).
    const lo = this._lenLo + n;
    this._lenLo = lo >>> 0;
    this._lenHi = (this._lenHi + Math.floor(lo / 4294967296)) >>> 0;

    let i = 0;
    if (this._len > 0) {
      const need = 64 - this._len;
      if (n < need) {
        this._buf.set(data, this._len);
        this._len += n;
        return this;
      }
      this._buf.set(data.subarray(0, need), this._len);
      compress(this._h, this._buf, 0);
      this._len = 0;
      i = need;
    }
    for (; i + 64 <= n; i += 64) {
      compress(this._h, data, i);
    }
    if (i < n) {
      this._buf.set(data.subarray(i), 0);
      this._len = n - i;
    }
    return this;
  }

  /**
   * Finalize and return the 20-byte digest. Does NOT mutate this object:
   * padding is applied to copies of the state and the partial buffer, so the
   * hash can keep being fed afterwards (hashlib behaves the same way).
   * @returns {Uint8Array} 20 bytes
   */
  digest() {
    const used = this._len;
    // 0x80 terminator plus the 8-byte length must fit; otherwise spill into a
    // second block.
    const padLen = used < 56 ? 64 : 128;
    PAD.fill(0, 0, padLen);
    PAD.set(this._buf.subarray(0, used), 0);
    PAD[used] = 0x80;

    // Message length in BITS, big-endian, in the last 8 bytes.
    const bitsHi = ((this._lenHi << 3) | (this._lenLo >>> 29)) >>> 0;
    const bitsLo = (this._lenLo << 3) >>> 0;
    let p = padLen - 8;
    PAD[p] = (bitsHi >>> 24) & 0xff;
    PAD[p + 1] = (bitsHi >>> 16) & 0xff;
    PAD[p + 2] = (bitsHi >>> 8) & 0xff;
    PAD[p + 3] = bitsHi & 0xff;
    PAD[p + 4] = (bitsLo >>> 24) & 0xff;
    PAD[p + 5] = (bitsLo >>> 16) & 0xff;
    PAD[p + 6] = (bitsLo >>> 8) & 0xff;
    PAD[p + 7] = bitsLo & 0xff;

    const h = new Uint32Array(this._h);
    for (let off = 0; off < padLen; off += 64) {
      compress(h, PAD, off);
    }

    const out = new Uint8Array(20);
    for (let i = 0, o = 0; i < 5; i++, o += 4) {
      const v = h[i];
      out[o] = (v >>> 24) & 0xff;
      out[o + 1] = (v >>> 16) & 0xff;
      out[o + 2] = (v >>> 8) & 0xff;
      out[o + 3] = v & 0xff;
    }
    return out;
  }

  /**
   * Snapshot of this hash object; the copy can be advanced independently.
   * @returns {SHA1}
   */
  copy() {
    const c = new SHA1();
    c._h.set(this._h);
    c._buf.set(this._buf);
    c._len = this._len;
    c._lenLo = this._lenLo;
    c._lenHi = this._lenHi;
    return c;
  }
}

/**
 * Create a new hash object, optionally seeded with data — `hashlib.sha1(data)`.
 * @param {Uint8Array} [initialBytes]
 * @returns {SHA1}
 */
export function create(initialBytes) {
  const h = new SHA1();
  if (initialBytes !== undefined && initialBytes !== null) h.update(initialBytes);
  return h;
}

// `new` is the hashlib spelling; exported under that name for callers that do
// `import * as sha1` and then `sha1.new(...)`.
export { create as new };

export default { digest_size, block_size, name, new: create, create, SHA1 };

