import sha1mod, { SHA1, create, digest_size, block_size } from '/output/lib/hash/sha1.mjs';
import * as ns from '/output/lib/hash/sha1.mjs';

const hex = (u8) => Array.from(u8, b => b.toString(16).padStart(2, '0')).join('');
const enc = (s) => new TextEncoder().encode(s);
let fails = 0;
const eq = (label, got, want) => {
  const ok = got === want;
  if (!ok) fails++;
  console.log((ok ? 'PASS' : 'FAIL') + ' ' + label + (ok ? '' : `\n  got  ${got}\n  want ${want}`));
};

const d = (s) => hex(create(enc(s)).digest());

eq("''", d(''), 'da39a3ee5e6b4b0d3255bfef95601890afd80709');
eq("'abc'", d('abc'), 'a9993e364706816aba3e25717850c26c9cd0d89d');
eq('448-bit', d('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'), '84983e441c3bd26ebaae4aa1f95129e5e54670f1');
eq('896-bit', d('abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu'), 'a49b2446a02c645bf419f995b67091253a04a259');
eq("'a'*1000000", d('a'.repeat(1000000)), '34aa973cd4c4daa4f61eeb2bdbad27316534016f');

// streaming: 'abc' one byte at a time
{
  const h = new SHA1();
  for (const ch of 'abc') h.update(enc(ch));
  eq('stream abc 1-byte', hex(h.digest()), 'a9993e364706816aba3e25717850c26c9cd0d89d');
}

// padding boundaries + streaming equivalence, all chunk sizes
const rnd = new Uint8Array(300);
for (let i = 0; i < rnd.length; i++) rnd[i] = (i * 37 + 11) & 0xff;
for (const len of [0,1,54,55,56,57,63,64,65,119,120,127,128,129,191,192,256,300]) {
  const data = rnd.subarray(0, len);
  const single = hex(create(data).digest());
  for (const chunk of [1,2,3,7,13,16,31,32,55,63,64,65,100,1000]) {
    const h = new SHA1();
    for (let i = 0; i < len; i += chunk) h.update(data.subarray(i, Math.min(i + chunk, len)));
    if (hex(h.digest()) !== single) { fails++; console.log(`FAIL stream len=${len} chunk=${chunk}`); }
  }
}
console.log('PASS streaming/padding matrix');

// digest() must not mutate state
{
  const h = new SHA1();
  h.update(enc('ab'));
  const d1 = hex(h.digest());
  const d2 = hex(h.digest());
  eq('digest idempotent', d1, d2);
  h.update(enc('c'));
  eq('digest non-mutating (continue)', hex(h.digest()), 'a9993e364706816aba3e25717850c26c9cd0d89d');
}

// copy() independence
{
  const h = new SHA1();
  h.update(enc('ab'));
  const c = h.copy();
  c.update(enc('XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'));
  c.digest();
  h.update(enc('c'));
  eq('copy independence', hex(h.digest()), 'a9993e364706816aba3e25717850c26c9cd0d89d');
  const c2 = create(enc('ab')).copy();
  c2.update(enc('c'));
  eq('copy continues', hex(c2.digest()), 'a9993e364706816aba3e25717850c26c9cd0d89d');
}

// long input crossing many blocks fed at odd boundary, plus a large single update
{
  const big = new Uint8Array(1000000).fill(0x61);
  const h = new SHA1();
  h.update(big.subarray(0, 999999));
  h.update(big.subarray(999999));
  eq('split million', hex(h.digest()), '34aa973cd4c4daa4f61eeb2bdbad27316534016f');
}

// module surface
eq('digest_size', String(digest_size), '20');
eq('block_size', String(block_size), '64');
eq('default.new', String(typeof sha1mod.new), 'function');
eq('ns.new', String(typeof ns.new), 'function');
eq('default.new works', hex(sha1mod.new(enc('abc')).digest()), 'a9993e364706816aba3e25717850c26c9cd0d89d');
eq('no-arg create', hex(create().digest()), 'da39a3ee5e6b4b0d3255bfef95601890afd80709');
eq('instance digest_size', String(new SHA1().digest_size), '20');

// HMAC-SHA1 + PBKDF2 sanity (inlined, RFC 6070) to prove it composes
function hmacSha1(key, msg) {
  if (key.length > 64) key = create(key).digest();
  const k = new Uint8Array(64); k.set(key);
  const ip = new Uint8Array(64), op = new Uint8Array(64);
  for (let i = 0; i < 64; i++) { ip[i] = k[i] ^ 0x36; op[i] = k[i] ^ 0x5c; }
  const inner = create(ip); inner.update(msg);
  const outer = create(op); outer.update(inner.digest());
  return outer.digest();
}
eq('hmac rfc2202 #1', hex(hmacSha1(new Uint8Array(20).fill(0x0b), enc('Hi There'))), 'b617318655057264e28bc0b6fb378c8ef146be00');
eq('hmac rfc2202 #2', hex(hmacSha1(enc('Jefe'), enc('what do ya want for nothing?'))), 'effcdf6ae5eb2fa2d27416d5f184df9c259a7c79');
eq('hmac long key', hex(hmacSha1(new Uint8Array(80).fill(0xaa), enc('Test Using Larger Than Block-Size Key - Hash Key First'))), 'aa4ae5e15272d00e95705637ce8a3b55ed402112');

function pbkdf2(pw, salt, iters, dkLen) {
  const out = []; let total = 0;
  for (let i = 1; total < dkLen; i++) {
    const blk = new Uint8Array(salt.length + 4);
    blk.set(salt); blk[salt.length] = (i >>> 24) & 0xff; blk[salt.length+1] = (i >>> 16) & 0xff;
    blk[salt.length+2] = (i >>> 8) & 0xff; blk[salt.length+3] = i & 0xff;
    let u = hmacSha1(pw, blk); const t = u.slice();
    for (let j = 1; j < iters; j++) { u = hmacSha1(pw, u); for (let k = 0; k < 20; k++) t[k] ^= u[k]; }
    out.push(t); total += 20;
  }
  const cat = new Uint8Array(total); let o = 0;
  for (const b of out) { cat.set(b, o); o += b.length; }
  return cat.subarray(0, dkLen);
}
eq('pbkdf2 c=1', hex(pbkdf2(enc('password'), enc('salt'), 1, 20)), '0c60c80f961f0e71f3a9b524af6012062fe037a6');
eq('pbkdf2 c=2', hex(pbkdf2(enc('password'), enc('salt'), 2, 20)), 'ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957');
eq('pbkdf2 c=4096', hex(pbkdf2(enc('password'), enc('salt'), 4096, 20)), '4b007901b765489abead49d926f721d065a429c1');
eq('pbkdf2 case A', hex(pbkdf2(enc("p'_xyB9J"), enc('$2b$12$aTIircdJsS8iO3WFg3aKsE'), 500, 20)), '8dc01b919e750ff1d42d9066b1cb46cbd79fbaca');
eq('pbkdf2 emoji', hex(pbkdf2(enc('\u{1F600}\u{1F511}'), enc('\u{1F9C2}'), 50, 20)), 'a5dac9673a93a95cc562585930bdd0d92a3dd093');

const t0 = Date.now();
pbkdf2(enc('=BH[kuEw'), enc('salt_740344'), 10000, 20);
console.log('10000-iteration timing: ' + (Date.now() - t0) + 'ms');

console.log(fails === 0 ? 'ALL OK' : fails + ' FAILURES');
process.exit(fails === 0 ? 0 : 1);
EOF
